const crypto = require('crypto');
const item = $input.first().json;

// Create content hash from first 1000 chars of normalized content
const normalized = (item.raw_content || item.title || '')
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 1000);

const hash = crypto.createHash('sha256').update(normalized).digest('hex').slice(0, 16);

return [{ json: { ...item, content_hash: hash } }];
